+@using sv_a633664ca2484347ab42ec0c427339fc
+@rendermode InteractiveServer
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h3 class="mb-3">Project Board</h3>
+
+@if (isLoading)
+{
+    <div class="d-flex justify-content-center p-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @errorMessage
+        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadTasks">Retry</button>
+    </div>
+}
+else
+{
+    <BoardStats TotalCount="allTasks.Count"
+                TodoCount="TodoTasks.Count"
+                InProgressCount="InProgressTasks.Count"
+                DoneCount="DoneTasks.Count"
+                OverdueCount="OverdueCount" />
+
+    <TaskSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />
+
+    <div class="row g-3">
+        <KanbanColumn ColumnName="To Do"
+                      Tasks="TodoTasks"
+                      CanMoveLeft="false"
+                      CanMoveRight="true"
+                      OnMoveRight="task => MoveTask(task, \"In Progress\")"
+                      OnTaskCreated="data => CreateTask(data, \"To Do\")" />
+
+        <KanbanColumn ColumnName="In Progress"
+                      Tasks="InProgressTasks"
+                      CanMoveLeft="true"
+                      CanMoveRight="true"
+                      OnMoveLeft="task => MoveTask(task, \"To Do\")"
+                      OnMoveRight="task => MoveTask(task, \"Done\")"
+                      OnTaskCreated="data => CreateTask(data, \"In Progress\")" />
+
+        <KanbanColumn ColumnName="Done"
+                      Tasks="DoneTasks"
+                      CanMoveLeft="true"
+                      CanMoveRight="false"
+                      OnMoveLeft="task => MoveTask(task, \"In Progress\")"
+                      OnTaskCreated="data => CreateTask(data, \"Done\")" />
+    </div>
+}
+
+@code {
+    [Inject] private ITaskService TaskService { get; set; } = default!;
+
+    private List<TaskItem> allTasks = new();
+    private string searchTerm = "";
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private static readonly string[] Columns = { "To Do", "In Progress", "Done" };
+
+    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(searchTerm)
+        ? allTasks
+        : allTasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
+
+    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();
+    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void HandleSearchChanged(string term)
+    {
+        searchTerm = term;
+    }
+
+    private async Task MoveTask(TaskItem task, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            var index = allTasks.FindIndex(t => t.Id == task.Id);
+            if (index >= 0)
+            {
+                allTasks[index] = task with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
+    {
+        try
+        {
+            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
+            // The service creates with a default status; update to the target column if needed
+            if (newTask.Status != status)
+            {
+                await TaskService.UpdateTaskStatusAsync(newTask.Id, status);
+                newTask = newTask with { Status = status };
+            }
+            allTasks.Add(newTask);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
+

